def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

num = int(input())
print('Prime' if is_prime(num) else 'Not Prime')

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n-1)

print(factorial(5))

def reverse_string(s):
    return s[::-1]

